def get_component_sizes_for_color(grid, color):
    """Get max component size for a given color"""
    h, w = len(grid), len(grid[0])
    visited = set()
    max_size = 0

    for r in range(h):
        for c in range(w):
            if grid[r][c] == color and (r,c) not in visited:
                q = [(r,c)]
